1	import { Router } from "express";
2	import { eq } from "drizzle-orm";
3	import type { Db } from "@paperclipai/db";
4	import { authUsers } from "@paperclipai/db";
5	import {
6	  authSessionSchema,
7	  currentUserProfileSchema,
8	  updateCurrentUserProfileSchema,
9	} from "@paperclipai/shared";
10	import { unauthorized } from "../errors.js";
11	import { expressHandler } from "../http/express-adapter.js";
12	import type { Handler } from "../http/types.js";
13	import type { StorageService } from "../storage/types.js";
14	
15	async function loadCurrentUserProfile(db: Db, userId: string) {
16	  const user = await db
17	    .select({
18	      id: authUsers.id,
19	      email: authUsers.email,
20	      name: authUsers.name,
21	      image: authUsers.image,
22	    })
23	    .from(authUsers)
24	    .where(eq(authUsers.id, userId))
25	    .then((rows) => rows[0] ?? null);
26	
27	  if (!user) {
28	    throw unauthorized("Signed-in user not found");
29	  }
30	
31	  return currentUserProfileSchema.parse({
32	    id: user.id,
33	    email: user.email ?? null,
34	    name: user.name ?? null,
35	    image: user.image ?? null,
36	  });
37	}
38	
39	function buildHandlers(db: Db) {
40	  // server/src/routes/auth.ts:40
41	  const getSession: Handler = async (ctx) => {
42	    if (ctx.actor?.type !== "board" || !ctx.actor.userId) {
43	      throw unauthorized("Board authentication required");
44	    }
45	
46	    const user = await loadCurrentUserProfile(db, ctx.actor.userId);
47	    // NOTE: req.actor.source is not available on ActorContext; the session id
48	    // no longer embeds the source segment. Previously: `paperclip:<source>:<userId>`.
49	    // TODO(cloudflare): verify auth flow in Workers
50	    return Response.json(authSessionSchema.parse({
51	      session: {
52	        id: `paperclip:session:${ctx.actor.userId}`,
53	        userId: ctx.actor.userId,
54	      },
55	      user,
56	    }));
57	  };
58	
59	  // server/src/routes/auth.ts:55
60	  const getProfile: Handler = async (ctx) => {
61	    if (ctx.actor?.type !== "board" || !ctx.actor.userId) {
62	      throw unauthorized("Board authentication required");
63	    }
64	
65	    return Response.json(await loadCurrentUserProfile(db, ctx.actor.userId));
66	  };
67	
68	  // server/src/routes/auth.ts:63
69	  const patchProfile: Handler = async (ctx) => {
70	    if (ctx.actor?.type !== "board" || !ctx.actor.userId) {
71	      throw unauthorized("Board authentication required");
72	    }
73	
74	    const body = await ctx.json();
75	    const patch = updateCurrentUserProfileSchema.parse(body);
76	    const now = new Date();
77	
78	    const updated = await db
79	      .update(authUsers)
80	      .set({
81	        name: patch.name,
82	        ...(patch.image !== undefined ? { image: patch.image } : {}),
83	        updatedAt: now,
84	      })
85	      .where(eq(authUsers.id, ctx.actor.userId))
86	      .returning({
87	        id: authUsers.id,
88	        email: authUsers.email,
89	        name: authUsers.name,
90	        image: authUsers.image,
91	      })
92	      .then((rows) => rows[0] ?? null);
93	
94	    if (!updated) {
95	      throw unauthorized("Signed-in user not found");
96	    }
97	
98	    return Response.json(currentUserProfileSchema.parse({
99	      id: updated.id,
100	      email: updated.email ?? null,
101	      name: updated.name ?? null,
102	      image: updated.image ?? null,
103	    }));
104	  };
105	
106	  return { getSession, getProfile, patchProfile };
107	}
108	
109	export function authRoutes(db: Db) {
110	  const router = Router();
111	  const { getSession, getProfile, patchProfile } = buildHandlers(db);
112	
113	  // None of these handlers touch storage; supply a sentinel so expressHandler's
114	  // AdapterDeps type is satisfied without widening the public signature.
115	  const storageSentinel = new Proxy({} as StorageService, {
116	    get(_target, prop) {
117	      throw new Error(`auth handler unexpectedly accessed storage.${String(prop)}`);
118	    },
119	  });
120	  const deps = { db, storage: storageSentinel };
121	
122	  router.get("/get-session", expressHandler(getSession, deps));
123	  router.get("/profile", expressHandler(getProfile, deps));
124	  router.patch("/profile", expressHandler(patchProfile, deps));
125	
126	  return router;
127	}
